function siapkanTabelIzinSakit(mysqli $conn): bool
{
    $sql = "CREATE TABLE IF NOT EXISTS izin_sakit (
        id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
        karyawan_id INT NOT NULL, department_id INT NOT NULL, mulai_at DATETIME NOT NULL, selesai_at DATETIME NOT NULL,
        total_menit INT UNSIGNED NOT NULL, deskripsi TEXT NOT NULL, nomor_kontak VARCHAR(50) NOT NULL,
        karyawan_pengganti_id INT NOT NULL, status ENUM('menunggu','disetujui','ditolak') NOT NULL DEFAULT 'menunggu',
        tahap_persetujuan ENUM('pic','koordinator','manager','selesai') NOT NULL DEFAULT 'pic', dibuat_oleh_user_id INT NOT NULL,
        diproses_oleh_user_id INT NULL, catatan_persetujuan TEXT NULL, diproses_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
        KEY idx_sakit_department (department_id), KEY idx_sakit_status (status),
        CONSTRAINT fk_sakit_karyawan FOREIGN KEY (karyawan_id) REFERENCES karyawan(id) ON DELETE CASCADE,
        CONSTRAINT fk_sakit_pengganti FOREIGN KEY (karyawan_pengganti_id) REFERENCES karyawan(id) ON DELETE RESTRICT,
        CONSTRAINT fk_sakit_pembuat FOREIGN KEY (dibuat_oleh_user_id) REFERENCES users(id) ON DELETE RESTRICT,
        CONSTRAINT fk_sakit_pemroses FOREIGN KEY (diproses_oleh_user_id) REFERENCES users(id) ON DELETE SET NULL
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4";
    if (mysqli_query($conn, $sql) !== true) return false;
    $kolom = mysqli_query($conn, "SHOW COLUMNS FROM izin_sakit LIKE 'surat_sakit_file'");
    if ($kolom && mysqli_num_rows($kolom) === 0) mysqli_query($conn, "ALTER TABLE izin_sakit ADD COLUMN surat_sakit_file VARCHAR(255) NULL AFTER deskripsi");
    if ($kolom) mysqli_free_result($kolom);
    return siapkanTahapPersetujuanIzin($conn, 'izin_sakit');
}

function labelDurasiSakit(int $menit): string
{
    $hari = intdiv($menit, 1440); $sisa = $menit % 1440; $jam = intdiv($sisa, 60); $sisaMenit = $sisa % 60; $bagian = [];
    if ($hari > 0) $bagian[] = $hari . ' hari'; if ($jam > 0) $bagian[] = $jam . ' jam'; if ($sisaMenit > 0 || $bagian === []) $bagian[] = $sisaMenit . ' menit';
    return implode(' ', $bagian);
}

