$tahapRole = tahapPersetujuanIzinUntukRole($role); $bolehSetuju = $langsungSuperadmin || $tahapRole !== null; $bolehInput = in_array($role, ['admin', 'superadmin'], true);
$form = ['department_id' => '', 'position' => '', 'karyawan_id' => '', 'mulai_at' => '', 'selesai_at' => '', 'deskripsi' => '', 'nomor_kontak' => '', 'karyawan_pengganti_id' => ''];

