        else { $userId = (int) $_SESSION['user']['id']; $berhasil = $langsungSuperadmin ? prosesKeputusanLangsungSuperadminIzin($conn, 'izin_sakit', $id, $role, $keputusan, $catatan, $userId) : prosesKeputusanPersetujuanIzin($conn, 'izin_sakit', $id, (int) $departmentId, $role, $keputusan, $catatan, $userId);
            if ($berhasil) { catatAktivitas($conn, 'Memproses izin sakit ID ' . $id . ' menjadi ' . $keputusan . '.'); header('Location: izin-sakit.php'); exit; }
            $pesan = 'Tahap persetujuan tidak sesuai atau data sudah diproses.'; }
    } elseif ($aksi === 'hapus' && $role === 'superadmin') {
        $id = (int) ($_POST['sakit_id'] ?? 0);
        if ($id <= 0) $pesan = 'Data izin sakit tidak valid.';
        else {
            $stmt = mysqli_prepare($conn, 'DELETE FROM izin_sakit WHERE id = ?');
            mysqli_stmt_bind_param($stmt, 'i', $id); mysqli_stmt_execute($stmt);
            if (mysqli_stmt_affected_rows($stmt) > 0) { mysqli_stmt_close($stmt); catatAktivitas($conn, 'Menghapus izin sakit ID ' . $id . '.'); header('Location: izin-sakit.php'); exit; }
            mysqli_stmt_close($stmt); $pesan = 'Data izin sakit tidak ditemukan.';
        }
    } elseif ($aksi === 'simpan' && !$bolehInput) $pesan = 'Hanya Admin dan superadmin yang dapat menginput izin sakit.';
    elseif ($aksi === 'simpan') {
        foreach (array_keys($form) as $kunci) $form[$kunci] = trim((string) ($_POST[$kunci] ?? ''));
        $karyawanId = (int) $form['karyawan_id']; $departemenForm = (int) $form['department_id']; $penggantiId = (int) $form['karyawan_pengganti_id']; $suratFile = null;
        $mulai = DateTimeImmutable::createFromFormat('Y-m-d\TH:i', $form['mulai_at']); $selesai = DateTimeImmutable::createFromFormat('Y-m-d\TH:i', $form['selesai_at']);
        $validWaktu = $mulai !== false && $selesai !== false && $selesai > $mulai; $menit = $validWaktu ? (int) (($selesai->getTimestamp() - $mulai->getTimestamp()) / 60) : 0;
        if ($departemenForm <= 0 || $form['position'] === '' || $karyawanId <= 0 || !$validWaktu || $form['deskripsi'] === '' || $form['nomor_kontak'] === '' || $penggantiId <= 0) $pesan = 'Semua data izin sakit wajib diisi dengan pilihan yang valid.';
        elseif ($karyawanId === $penggantiId || strlen($form['nomor_kontak']) > 50) $pesan = 'Karyawan pengganti harus berbeda dan nomor kontak maksimal 50 karakter.';
        elseif (roleOperasional() && $departemenForm !== (int) $departmentId) $pesan = 'Departemen berada di luar cakupan Anda.';
        elseif (isset($_FILES['surat_sakit']) && ($_FILES['surat_sakit']['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_NO_FILE) {
            $surat = $_FILES['surat_sakit'];
            if (($surat['error'] ?? UPLOAD_ERR_OK) !== UPLOAD_ERR_OK || (int) ($surat['size'] ?? 0) > 5 * 1024 * 1024 || strtolower(pathinfo((string) ($surat['name'] ?? ''), PATHINFO_EXTENSION)) !== 'pdf' || (new finfo(FILEINFO_MIME_TYPE))->file((string) $surat['tmp_name']) !== 'application/pdf') $pesan = 'Surat keterangan sakit harus berupa PDF maksimal 5 MB.';
            else { $folder = __DIR__ . '/../../storage/uploads/surat-sakit'; if (!is_dir($folder)) mkdir($folder, 0750, true); $namaFile = 'sakit-' . bin2hex(random_bytes(12)) . '.pdf'; if (!move_uploaded_file((string) $surat['tmp_name'], $folder . '/' . $namaFile)) $pesan = 'Surat keterangan sakit gagal diunggah.'; else $suratFile = 'uploads/surat-sakit/' . $namaFile; }
        }
        if ($pesan === '') {
            $cekKaryawan = mysqli_prepare($conn, 'SELECT id FROM karyawan WHERE id = ? AND department_id = ? AND position = ?'); mysqli_stmt_bind_param($cekKaryawan, 'iis', $karyawanId, $departemenForm, $form['position']); mysqli_stmt_execute($cekKaryawan); $validKaryawan = mysqli_fetch_assoc(mysqli_stmt_get_result($cekKaryawan)); mysqli_stmt_close($cekKaryawan);
            $cekPengganti = mysqli_prepare($conn, 'SELECT id FROM karyawan WHERE id = ? AND department_id = ? AND id <> ?'); mysqli_stmt_bind_param($cekPengganti, 'iii', $penggantiId, $departemenForm, $karyawanId); mysqli_stmt_execute($cekPengganti); $validPengganti = mysqli_fetch_assoc(mysqli_stmt_get_result($cekPengganti)); mysqli_stmt_close($cekPengganti);
            if (!$validKaryawan || !$validPengganti) $pesan = 'Karyawan atau pengganti tidak sesuai dengan departemen dan posisi yang dipilih.';
            else { $pembuat = (int) $_SESSION['user']['id']; $mulaiDb = $mulai->format('Y-m-d H:i:s'); $selesaiDb = $selesai->format('Y-m-d H:i:s');
                $stmt = mysqli_prepare($conn, 'INSERT INTO izin_sakit (karyawan_id, department_id, mulai_at, selesai_at, total_menit, deskripsi, surat_sakit_file, nomor_kontak, karyawan_pengganti_id, dibuat_oleh_user_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'); mysqli_stmt_bind_param($stmt, 'iississsii', $karyawanId, $departemenForm, $mulaiDb, $selesaiDb, $menit, $form['deskripsi'], $suratFile, $form['nomor_kontak'], $penggantiId, $pembuat);
                if (mysqli_stmt_execute($stmt)) { $id = (int) mysqli_insert_id($conn); mysqli_stmt_close($stmt); catatAktivitas($conn, 'Membuat izin sakit ID ' . $id . '.'); header('Location: izin-sakit.php'); exit; } mysqli_stmt_close($stmt); $pesan = 'Izin sakit gagal disimpan.'; }
        }
    }
}

$departemenPilihan = ambilDepartemenPilihan($conn, roleOperasional() ? (int) $departmentId : null); $posisiPerDepartemen = ambilPosisiPerDepartemen($conn, roleOperasional() ? (int) $departmentId : null);
$dataKaryawan = []; $hasilKaryawan = mysqli_query($conn, 'SELECT id, emp_id, employee_name, position, department, department_id FROM karyawan WHERE department_id IS NOT NULL' . (roleOperasional() ? ' AND department_id = ' . (int) $departmentId : '') . ' ORDER BY employee_name'); while ($k = mysqli_fetch_assoc($hasilKaryawan)) $dataKaryawan[] = ['id' => (int) $k['id'], 'emp_id' => $k['emp_id'], 'nama' => $k['employee_name'], 'posisi' => $k['position'], 'departemen' => $k['department'], 'department_id' => (int) $k['department_id']];
