<section class="data-card izin-data-card"><div class="data-card-header"><h2>Daftar Izin Sakit</h2></div><div class="table-wrapper"><table><thead><tr><th>ID</th><th>Karyawan</th><th>Posisi</th><th>Departemen</th><th>Mulai</th><th>Selesai</th><th>Durasi</th><th>Keterangan</th><th>Surat Pendukung</th><th>Kontak</th><th>Pengganti</th><th>Status</th><th>Dibuat Oleh</th><th class="izin-actions-header">Aksi</th></tr></thead><tbody><?php if ($daftar && mysqli_num_rows($daftar) > 0): while ($s = mysqli_fetch_assoc($daftar)): $tahap = (string) $s['tahap_persetujuan']; $bolehProses = $s['status'] === 'menunggu' && ($langsungSuperadmin || ($bolehSetuju && $tahap === $tahapRole)); ?><tr><td><?= (int) $s['id']; ?></td><td><?= htmlspecialchars($s['emp_id'] . ' - ' . $s['employee_name']); ?></td><td><?= htmlspecialchars($s['position']); ?></td><td><?= htmlspecialchars($s['department']); ?></td><td><?= htmlspecialchars($s['mulai_at']); ?></td><td><?= htmlspecialchars($s['selesai_at']); ?></td><td><?= htmlspecialchars(labelDurasiSakit((int) $s['total_menit'])); ?></td><td class="izin-description-cell"><?= nl2br(htmlspecialchars($s['deskripsi'])); ?></td><td><?php if (!empty($s['surat_sakit_file'])): ?><a class="btn btn-primary" href="surat-sakit.php?file=<?= rawurlencode(basename((string) $s['surat_sakit_file'])); ?>" target="_blank" rel="noopener">Lihat Surat</a><?php else: ?>-<?php endif; ?></td><td><?= htmlspecialchars($s['nomor_kontak']); ?></td><td><?= htmlspecialchars($s['pengganti_emp_id'] . ' - ' . $s['pengganti_nama']); ?></td><td><span class="status-badge status-<?= htmlspecialchars($s['status']); ?>"><?= htmlspecialchars(labelStatusPersetujuanIzin($s['status'], $tahap, $s['role_pemroses'])); ?></span></td><td><?= htmlspecialchars($s['nama_pembuat']); ?></td><td class="izin-actions"><?php if ($bolehProses): ?><form method="POST"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(tokenCsrf()); ?>"><input type="hidden" name="aksi" value="keputusan"><input type="hidden" name="sakit_id" value="<?= (int) $s['id']; ?>"><input name="catatan" placeholder="Catatan/alasan penolakan"><button class="btn btn-success" name="keputusan" value="disetujui">Setujui</button><button class="btn btn-danger" name="keputusan" value="ditolak">Tolak</button></form><?php else: ?><?php endif; ?><?php if ($role === 'superadmin'): ?><form method="POST" class="delete-izin-form" onsubmit="return confirm('Hapus data izin sakit ini?');"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(tokenCsrf()); ?>"><input type="hidden" name="aksi" value="hapus"><input type="hidden" name="sakit_id" value="<?= (int) $s['id']; ?>"><button class="btn btn-danger" type="submit">Hapus</button></form><?php endif; ?></td></tr><?php endwhile; else: ?><tr><td colspan="14" class="empty-table">Belum ada data izin sakit.</td></tr><?php endif; ?></tbody></table></div></section>
<?php if ($bolehInput): ?><script>(() => { const employees = <?= json_encode($dataKaryawan, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES); ?>, positions = <?= json_encode($posisiPerDepartemen, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES); ?>; const d = document.getElementById('sakit-department'), p = document.getElementById('sakit-position'), k = document.getElementById('sakit-karyawan'), gd = document.getElementById('sakit-pengganti-department'), gp = document.getElementById('sakit-pengganti-position'), g = document.getElementById('sakit-pengganti'), info = document.getElementById('sakit-pengganti-info'), mulai = document.getElementById('sakit-mulai'), selesai = document.getElementById('sakit-selesai'), durasi = document.getElementById('sakit-durasi'); const opt = (v,t) => { const o=document.createElement('option'); o.value=String(v); o.textContent=t; return o; }; const reset = (element, text) => { element.replaceChildren(opt('', text)); element.disabled=true; }; const isiPengganti = () => { const daftar=employees.filter(x=>String(x.department_id)===d.value&&(!gp.value||x.posisi===gp.value)&&String(x.id)!==k.value); g.replaceChildren(opt('', daftar.length?'Pilih karyawan pengganti':'Tidak ada karyawan yang sesuai')); daftar.forEach(x=>g.append(opt(x.id,`${x.emp_id} - ${x.nama}`))); g.disabled=!daftar.length; info.hidden=true; info.textContent=''; }; const isiPosisiPengganti = () => { const daftar=[...new Set(positions[gd.value]||[])]; gp.replaceChildren(opt('', daftar.length?'Pilih posisi':'Tidak ada posisi pada departemen ini')); daftar.forEach(x=>gp.append(opt(x,x))); gp.disabled=!daftar.length; reset(g,'Pilih departemen dan posisi terlebih dahulu'); info.hidden=true; }; const isiDepartemenPengganti = () => { gd.replaceChildren(opt('','Pilih departemen')); Object.entries(<?= json_encode($departemenPilihan, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES); ?>).forEach(([id,nama])=>gd.append(opt(id,nama))); gd.value=d.value; gd.disabled=true; isiPosisiPengganti(); }; const isiKaryawan = () => { const daftar=employees.filter(x=>String(x.department_id)===d.value&&x.posisi===p.value); k.replaceChildren(opt('', daftar.length?'Pilih karyawan':'Tidak ada karyawan')); daftar.forEach(x=>k.append(opt(x.id,`${x.emp_id} - ${x.nama}`))); k.disabled=!daftar.length; isiDepartemenPengganti(); }; d.addEventListener('change',()=>{ const daftar=[...new Set(positions[d.value]||[])]; p.replaceChildren(opt('',daftar.length?'Pilih posisi':'Tidak ada posisi')); daftar.forEach(x=>p.append(opt(x,x))); p.disabled=!daftar.length; reset(k,'Pilih departemen dan posisi terlebih dahulu'); reset(gd,'Pilih karyawan terlebih dahulu'); reset(gp,'Pilih departemen terlebih dahulu'); reset(g,'Pilih departemen dan posisi terlebih dahulu'); }); p.addEventListener('change',isiKaryawan); k.addEventListener('change',()=>{ if (gd.value === d.value) isiPengganti(); }); gd.addEventListener('change',isiPosisiPengganti); gp.addEventListener('change',isiPengganti); g.addEventListener('change',()=>{ const item=employees.find(x=>String(x.id)===g.value); info.hidden=!item; info.textContent=item?`${item.emp_id} — ${item.nama} (${item.posisi})`:''; }); const hitung=()=>{ if(!mulai.value||!selesai.value){durasi.value='-';return;} const beda=new Date(selesai.value)-new Date(mulai.value); if(beda<=0){durasi.value='Waktu tidak valid';return;} const m=Math.round(beda/60000), h=Math.floor(m/60), s=m%60, hari=Math.floor(h/24); durasi.value=`${hari?hari+' hari ':''}${h%24?h%24+' jam ':''}${s?s+' menit':''}`.trim(); }; mulai.addEventListener('change',hitung); selesai.addEventListener('change',hitung); })();</script><?php endif; ?>
